<div class="my-6 space-y-4 rounded-xl border p-4" x-data="audioSettings(@js(route('audio.index',$story)))" @vsg-audio.window="sounds=$event.detail">
<h3 class="font-serif text-xl">Music &amp; default sounds</h3>
<label class="field">Game music<div class="audio-select-row" x-data="audioPreview('music')" x-effect="setSound(sounds.find(s=>s.id===Number(settings.music_id)))" @vsg-audio-preview-stop.window="stop()" @vsg-audio-categories.window="categories=$event.detail"><select class="audio-category-select" aria-label="Audio category" x-model="category"><option value="">All categories</option><template x-for="(name,key) in categories" :key="key"><option :value="key" x-text="name"></option></template></select><div class="min-w-0 flex-1"><select x-model="settings.music_id" @change="settings.music_id=$event.target.value?Number($event.target.value):null;save()"><option value="">No music</option><template x-for="s in sounds.filter(s=>!category||(s.category||'effects')===category||Number(s.id)===Number(sound?.id))" :key="s.id"><option :value="s.id" x-text="s.name"></option></template></select></div><button type="button" class="btn-secondary audio-preview-button" :disabled="!sound?.url" :aria-label="playing?'Stop audio preview':'Play selected audio'" :title="playing?'Stop':'Listen'" :aria-pressed="playing" @click="toggle()"><span x-text="playing?'\u25A0':'\u25B6'" aria-hidden="true"></span></button></div></label>
<label class="area-checkbox"><input type="checkbox" x-model="settings.music_loop" @change="save()"><span>Loop music</span></label>
<div class="audio-defaults-heading text-xs"><strong>Action</strong><strong>Click sound</strong><strong>Action sound</strong></div>
<template x-for="(label,action) in actions" :key="action"><div class="audio-defaults-row" x-show="settings.defaults[action]"><span class="text-sm" x-text="label"></span><template x-for="event in ['click','action']" :key="event"><div class="audio-select-row" x-data="audioPreview('effects')" x-effect="setSound(sounds.find(s=>s.id===Number(settings.defaults[action]?.[event])))" @vsg-audio-preview-stop.window="stop()" @vsg-audio-categories.window="categories=$event.detail"><select class="audio-category-select" aria-label="Audio category" x-model="category"><option value="">All categories</option><template x-for="(name,key) in categories" :key="key"><option :value="key" x-text="name"></option></template></select><div class="min-w-0 flex-1"><select :aria-label="label+' '+event+' sound'" :value="settings.defaults[action]?.[event] || ''" @change="settings.defaults[action][event]=$event.target.value?Number($event.target.value):null;save()"><option value="">No sound (silent)</option><template x-for="s in sounds.filter(s=>!category||(s.category||'effects')===category||Number(s.id)===Number(sound?.id))" :key="s.id"><option :value="s.id" x-text="s.name"></option></template></select></div><button type="button" class="btn-secondary audio-preview-button" :disabled="!sound?.url" :aria-label="playing?'Stop audio preview':'Play selected audio'" :title="playing?'Stop':'Listen'" :aria-pressed="playing" @click="toggle()"><span x-text="playing?'\u25A0':'\u25B6'" aria-hidden="true"></span></button></div></template></div></template>
<section class="space-y-4 border-t pt-5">
<h3 class="font-serif text-xl">Description voices</h3>
<template x-for="(label,key) in voiceGroups" :key="key"><div class="space-y-3 rounded-lg border p-4" x-show="settings.voices?.[key]">
<h4 class="font-semibold" x-text="label"></h4>
<template x-if="settings.voices?.[key]"><div class="space-y-3">
<div class="grid gap-3 sm:grid-cols-2"><label class="field">Model<select x-model="settings.voices[key].model" @change="changeVoiceModel(key)"><option value="">Default model</option><template x-for="m in models" :key="m.id"><option :value="m.id" x-text="m.name"></option></template></select></label>
<label class="field">Voice<select x-model="settings.voices[key].voice" @change="save()"><option value="">Default voice</option><template x-for="v in voicesFor(key)" :key="v"><option :value="v" x-text="v"></option></template></select></label></div>
<template x-if="settings.voices[key].model.startsWith('google/')"><div class="grid gap-3 sm:grid-cols-2"><label class="field">Delivery instructions<textarea x-model="settings.voices[key].instructions" maxlength="1000" @change="save()"></textarea></label><label class="field">Temperature<input type="number" min="0" max="2" step="0.1" x-model.number="settings.voices[key].temperature" @change="save()"></label></div></template>
<label class="field" x-show="settings.voices[key].model.startsWith('heygen/')">Language (optional code)<input x-model="settings.voices[key].language" maxlength="10" @change="save()" placeholder="en"></label>
<button type="button" class="btn-secondary" @click="testVoice(key)">Test this voice</button>
</div></template></div></template>
<label class="field">Test text<textarea x-model="testText" maxlength="5000" rows="2"></textarea></label>
</section>
</div>
